#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long value;
    int mechanic;
    int k;
} Node;

static Node heap[100005];
static int heap_size;

static int less_node(Node a, Node b) {
    if (a.value != b.value) return a.value < b.value;
    return a.mechanic < b.mechanic;
}

static void push(Node x) {
    int i = ++heap_size;
    while (i > 1 && less_node(x, heap[i / 2])) {
        heap[i] = heap[i / 2];
        i /= 2;
    }
    heap[i] = x;
}

static Node pop_min(void) {
    Node result = heap[1];
    Node last = heap[heap_size--];
    int i = 1;

    while (i * 2 <= heap_size) {
        int child = i * 2;
        if (child + 1 <= heap_size && less_node(heap[child + 1], heap[child]))
            child++;
        if (!less_node(heap[child], last)) break;
        heap[i] = heap[child];
        i = child;
    }

    if (heap_size > 0) heap[i] = last;
    return result;
}

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *T = malloc((size_t)N * sizeof(int));
    long long *coeff = malloc((size_t)N * sizeof(long long));
    int *F = malloc((size_t)M * sizeof(int));

    for (int i = 0; i < N; i++) scanf("%d", &T[i]);
    for (int j = 0; j < M; j++) scanf("%d", &F[j]);

    qsort(T, N, sizeof(int), cmp_int);

    for (int j = 0; j < M; j++) {
        Node x = {0, j, 0};
        push(x);
    }

    for (int i = 0; i < N; i++) {
        Node x = pop_min();
        coeff[i] = x.value;

        x.k++;
        x.value = (long long)x.k * F[x.mechanic];
        push(x);
    }

    long long answer = 0;
    for (int i = 0; i < N; i++)
        answer += (long long)T[N - 1 - i] * coeff[i];

    printf("%lld\n", answer);

    free(T);
    free(coeff);
    free(F);
    return 0;
}
